', ['name' => 'calendar', 'class' => ''])</button><div class="staff-appointment-popover" role="dialog" aria-label="Choose confirmed appointment date and time" hidden><div class="appointment-calendar-head"><button type="button" data-month-step="-1" aria-label="Previous month">‹</button><strong data-month-label></strong><button type="button" data-month-step="1" aria-label="Next month">›</button></div><div class="appointment-weekdays" aria-hidden="true"><span>Su</span><span>Mo</span><span>Tu</span><span>We</span><span>Th</span><span>Fr</span><span>Sa</span></div><div class="appointment-days" role="grid"></div><div class="appointment-time"><label>Time</label><select data-hour aria-label="Hour">@for($hour = 1; $hour <= 12; $hour++)<option value="{{ sprintf('%02d', $hour) }}" @selected($hour === 9)>{{ sprintf('%02d', $hour) }}</option>@endfor</select><span>:</span><select data-minute aria-label="Minute">@for($minute = 0; $minute < 60; $minute++)<option value="{{ sprintf('%02d', $minute) }}">{{ sprintf('%02d', $minute) }}</option>@endfor</select><select data-period aria-label="AM or PM"><option>am</option><option>pm</option></select></div><div class="appointment-actions"><button type="button" data-clear>Clear</button><button type="button" data-today>Today</button><button type="button" class="appointment-done" data-done>Done</button></div></div></div><small class="label">Blank confirmation uses the first preferred option automatically.</small>@endif<label for="staff_notes">Internal staff notes</label><textarea id="staff_notes" name="staff_notes">{{ old('staff_notes', $booking->staff_notes) }}</textarea><button class="button" type="submit">Save booking</button></form></section>@endunless</div>
