<style>.staff-appointment-picker{position:relative}.form .staff-appointment-display{padding-right:42px;border:1px solid #8da2c2;background:#fff;box-shadow:0 2px 5px #10234312;cursor:pointer}.form .staff-appointment-display:focus{border-color:#315f9d;outline:2px solid #0969da35;outline-offset:1px;box-shadow:0 5px 16px #10234330}.staff-appointment-trigger{position:absolute;right:5px;top:5px;width:30px;height:30px;border:0;border-radius:5px;background:transparent;color:#152c4e;display:grid;place-items:center;cursor:pointer}.staff-appointment-trigger .icon{width:16px;height:16px}.staff-appointment-popover{position:absolute;z-index:1000;width:310px;max-height:calc(100vh - 16px);overflow-y:auto;padding:13px;background:#fff;border:2px solid #536b8b;border-radius:10px;box-shadow:0 12px 30px #071b3660;color:#0b1d38}.staff-appointment-popover[hidden]{display:none}.staff-appointment-popover .appointment-calendar-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}.staff-appointment-popover .appointment-calendar-head strong{font-size:14px}.staff-appointment-popover .appointment-calendar-head button,.staff-appointment-popover .appointment-actions button{width:auto;margin:0;border:1px solid #c3cee0;border-radius:5px;background:#fff;color:#173451;padding:5px 9px;font:inherit;cursor:pointer}.staff-appointment-popover .appointment-weekdays,.staff-appointment-popover .appointment-days{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;text-align:center}.staff-appointment-popover .appointment-weekdays{font-size:11px;font-weight:700;color:#53627a;margin-bottom:5px}.staff-appointment-popover .appointment-days button{height:32px;margin:0;border:1px solid transparent;border-radius:5px;background:#fff;color:#132a49;padding:0;font:inherit;cursor:pointer}.staff-appointment-popover .appointment-days button:hover{border-color:#315f9d;background:#edf4ff}.staff-appointment-popover .appointment-days button.today{border-color:#8296b2}.staff-appointment-popover .appointment-days button.selected{background:#0969da;border-color:#0758b8;color:#fff;font-weight:700}.staff-appointment-popover .appointment-day-spacer{height:32px}.staff-appointment-popover .appointment-time{display:flex;align-items:center;gap:6px;margin-top:12px;padding-top:11px;border-top:1px solid #d6deed}.staff-appointment-popover .appointment-time label{font-size:12px;font-weight:700;margin:0 auto 0 0}.staff-appointment-popover .appointment-time select{width:auto;border:1px solid #9aabc4;border-radius:5px;background:#fff;color:#132a49;padding:6px 4px;font:inherit}.staff-appointment-popover .appointment-actions{display:flex;align-items:center;gap:6px;margin-top:12px;padding-top:10px;border-top:1px solid #d6deed}.staff-appointment-popover .appointment-actions [data-today]{margin-right:auto}.staff-appointment-popover .appointment-actions .appointment-done{background:#182329;color:#fff;border-color:#182329}</style>
<script>
(() => {
    const picker = document.querySelector('[data-staff-picker]');
    if (!picker) return;
    const display = picker.querySelector('.staff-appointment-display');
    const stored = picker.querySelector('input[type="hidden"]');
    const popover = picker.querySelector('.staff-appointment-popover');
    const monthLabel = popover.querySelector('[data-month-label]');
    const dayGrid = popover.querySelector('.appointment-days');
    const hour = popover.querySelector('[data-hour]');
    const minute = popover.querySelector('[data-minute]');
    const period = popover.querySelector('[data-period]');
    const pad = value => String(value).padStart(2, '0');
    let selected = stored.value ? new Date(stored.value) : null;
    let shown = selected && !Number.isNaN(selected.getTime()) ? new Date(selected.getFullYear(), selected.getMonth(), 1) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
    const syncValue = () => {
        if (!selected) { stored.value = ''; display.value = ''; return; }
        let h = Number(hour.value) % 12 + (period.value === 'pm' ? 12 : 0);
        selected.setHours(h, Number(minute.value), 0, 0);
        stored.value = `${selected.getFullYear()}-${pad(selected.getMonth() + 1)}-${pad(selected.getDate())}T${pad(h)}:${pad(selected.getMinutes())}`;
        display.value = `${selected.toLocaleDateString('en-GB', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })} · ${hour.value}:${minute.value} ${period.value.toUpperCase()}`;
    };
    const render = () => {
        monthLabel.textContent = shown.toLocaleDateString('en-GB', { month: 'long', year: 'numeric' });
        dayGrid.replaceChildren();
        const offset = new Date(shown.getFullYear(), shown.getMonth(), 1).getDay();
        const count = new Date(shown.getFullYear(), shown.getMonth() + 1, 0).getDate();
        for (let i = 0; i < offset; i++) { const spacer = document.createElement('span'); spacer.className = 'appointment-day-spacer'; dayGrid.append(spacer); }
        for (let day = 1; day <= count; day++) {
            const button = document.createElement('button');
            button.type = 'button'; button.textContent = day;
            if (selected && selected.getFullYear() === shown.getFullYear() && selected.getMonth() === shown.getMonth() && selected.getDate() === day) button.classList.add('selected');
            const now = new Date(); if (day === now.getDate() && shown.getMonth() === now.getMonth() && shown.getFullYear() === now.getFullYear()) button.classList.add('today');
            button.addEventListener('click', () => { selected = new Date(shown.getFullYear(), shown.getMonth(), day); syncValue(); render(); });
            dayGrid.append(button);
        }
    };
    const open = () => {
        popover.hidden = false;
        if (popover.parentElement !== document.body) document.body.append(popover);
        display.setAttribute('aria-expanded', 'true'); render();
        const field = picker.getBoundingClientRect(); const width = Math.min(310, innerWidth - 16); popover.style.width = `${width}px`;
        const height = popover.getBoundingClientRect().height; let top = field.bottom + scrollY + 8;
        if (field.bottom + height + 8 > innerHeight) top = Math.max(scrollY + 8, field.top + scrollY - height - 8);
        if (top + height > scrollY + innerHeight - 8) top = scrollY + 8;
        popover.style.top = `${top}px`; popover.style.left = `${Math.min(Math.max(8, field.left + scrollX), scrollX + innerWidth - width - 8)}px`;
    };
    const close = () => { popover.hidden = true; display.setAttribute('aria-expanded', 'false'); picker.append(popover); };
    if (selected && !Number.isNaN(selected.getTime())) { let h = selected.getHours(); period.value = h >= 12 ? 'pm' : 'am'; h = h % 12 || 12; hour.value = pad(h); minute.value = pad(selected.getMinutes()); syncValue(); }
    display.addEventListener('focus', open); display.addEventListener('click', open);
    picker.querySelector('.staff-appointment-trigger').addEventListener('click', () => { open(); display.focus(); });
    popover.querySelectorAll('[data-month-step]').forEach(button => button.addEventListener('click', () => { shown.setMonth(shown.getMonth() + Number(button.dataset.monthStep)); render(); }));
    [hour, minute, period].forEach(control => control.addEventListener('change', syncValue));
    popover.querySelector('[data-today]').addEventListener('click', () => { const now = new Date(); selected = new Date(now.getFullYear(), now.getMonth(), now.getDate()); shown = new Date(now.getFullYear(), now.getMonth(), 1); syncValue(); render(); });
    popover.querySelector('[data-clear]').addEventListener('click', () => { selected = null; syncValue(); render(); });
    popover.querySelector('[data-done]').addEventListener('click', close);
    document.addEventListener('pointerdown', event => { if (!picker.contains(event.target) && !popover.contains(event.target)) close(); });
    display.addEventListener('keydown', event => { if (event.key === 'Escape') close(); });
})();
</script></body></html>
